    std::shared_ptr<Sample>editingSample()const{if(selected==MasterChannel)return {};auto&t=channel(selected);if(!t.sampler&&!t.clips.empty()){int i=(int)clamp(selectedClip<0?0:selectedClip,0,t.clips.size()-1);if(auto audio=clipAudio(t,t.clips[i]))return audio->missing?nullptr:audio;}return t.sample&&t.sample->missing?nullptr:t.sample;}
    Clip*editingClip(){if(selected==MasterChannel||channel(selected).clips.empty())return nullptr;auto&clips=channel(selected).clips;return &clips[(size_t)clamp(selectedClip<0?0:selectedClip,0,clips.size()-1)];}
    void audioParameter(int parameter){finishAudioRecording();auto*clip=editingClip();if(!clip||selected==MasterChannel||!editingSample())return;double values[]={clip->offset,clip->length,clip->gain>0?20*log10(clip->gain):-60,clip->fadeIn,clip->fadeOut};const wchar_t*labels[]={L"Начало аудиоклипа, секунды",L"Длина аудиоклипа, доли",L"Усиление клипа, dB",L"Fade in, секунды",L"Fade out, секунды"};if(parameter<0||parameter>4)return;auto result=TextPrompt::show(window,labels[parameter],number(values[parameter],3));if(!result)return;try{std::replace(result->begin(),result->end(),L',',L'.');double value=std::stod(*result);if(!std::isfinite(value))throw std::runtime_error("Invalid number");history();auto&sample=*editingSample();double duration=sample.left.size()/double(sample.rate);if(parameter==0){clip->warp=false;clip->warpAudio.reset();clip->warpReference.reset();clip->warpPoints.clear();clip->offset=clamp(value,0,std::max(0.,duration-.001));clip->length=std::min(clip->length,audioBeatLength(project,clip->beat,duration-clip->offset));}else if(parameter==1){double old=clip->length;clip->length=clamp(value,.001,clip->warp?256:audioBeatLength(project,clip->beat,duration-clip->offset));resizeWarp(*clip,old);}else if(parameter==2)clip->gain=(float)std::pow(10.,clamp(value,-60,12)/20.);else if(parameter==3)clip->fadeIn=clamp(value,0,songClock(project).duration(clip->beat,clip->beat+clip->length));else clip->fadeOut=clamp(value,0,songClock(project).duration(clip->beat,clip->beat+clip->length));project.bars=std::min(4096,std::max(project.bars,barsForEnd(clip->beat+clip->length)));changed();}catch(...){notify(L"Введи число, например 0.250");}}
    void clipContext(int track,int index,double beat){if(!clipSelection.count({track,index})){select(track);clipSelection={{track,index}};}selected=track;selectedClip=index;auto&t=channel(track);HMENU menu=CreatePopupMenu();AppendMenuW(menu,MF_STRING,7,L"Bounce in place / selected clips on this track");AppendMenuW(menu,MF_STRING,8,L"Bounce in place + 2 s tail");if(clipAudio(t,t.clips[index])){AppendMenuW(menu,MF_STRING,13,L"Edit with ARA / Melodyne / Vovious…");AppendMenuW(menu,MF_STRING,12,L"Warp audio / link selected clips…");}AppendMenuW(menu,MF_STRING,9,clipAudio(t,t.clips[index])?L"Open Sample Lab":L"Open Piano roll");AppendMenuW(menu,MF_STRING,10,L"Select every clip on this track");AppendMenuW(menu,MF_STRING,11,L"Loop selected clips");AppendMenuW(menu,MF_SEPARATOR,0,nullptr);AppendMenuW(menu,MF_STRING,1,L"Разрезать здесь");AppendMenuW(menu,MF_STRING,2,L"Дублировать клип");AppendMenuW(menu,MF_STRING,3,clipAudio(t,t.clips[index])!=nullptr?L"Открыть аудиоредактор":L"Сделать паттерн уникальным");AppendMenuW(menu,MF_STRING,4,L"Переименовать… / F2");AppendMenuW(menu,MF_STRING,5,t.clips[index].muted?L"Включить клип":L"Заглушить клип");HMENU palette=CreatePopupMenu();const wchar_t*colors[]={L"Цвет дорожки",L"Crimson",L"Amethyst",L"Antique gold",L"Midnight jade",L"Moonlight"};for(int i=0;i<6;i++)AppendMenuW(palette,MF_STRING,100+i,colors[i]);AppendMenuW(menu,MF_POPUP,(UINT_PTR)palette,L"Цвет клипа");AppendMenuW(menu,MF_STRING,6,L"Удалить клип / Delete");POINT point;GetCursorPos(&point);int id=TrackPopupMenu(menu,TPM_RETURNCMD,point.x,point.y,0,window,nullptr);DestroyMenu(menu);if(!id)return;if(id==7||id==8){bounceInPlace(track,id==8);return;}if(id==9){t.activePattern=t.clips[index].pattern;audioStart=audioSpan=0;showEditor(clipAudio(t,t.clips[index])?4:1);return;}if(id==10){clipSelection.clear();for(int n=0;n<(int)t.clips.size();n++)clipSelection.insert({track,n});InvalidateRect(window,nullptr,FALSE);return;}if(id==13){openAraClip(track,index);return;}if(id==12){openDesk(1);return;}if(id==11){loopSelected();return;}if(id==1){cutClip(track,index,beat);return;}if(id==4){renameClip();return;}if(id==6){eraseSelectedClips();return;}if(id==3&&clipAudio(t,t.clips[index])!=nullptr){showEditor(4);InvalidateRect(window,nullptr,FALSE);return;}if(id==3&&t.patterns.size()>=255){notify(L"Максимум 256 паттернов");return;}history();if(id==2){auto clip=t.clips[index];clip.beat+=clip.length;t.clips.push_back(clip);selectedClip=(int)t.clips.size()-1;clipSelection={{track,selectedClip}};project.bars=std::max(project.bars,barsForEnd(clip.beat+clip.length));}else if(id==3){Pattern pattern;pattern.name="Unique "+std::to_string(t.patterns.size()+2);pattern.length=patternLength(t,t.clips[index].pattern);pattern.notes=patternNotes(t,t.clips[index].pattern);t.patterns.push_back(std::move(pattern));t.clips[index].pattern=t.activePattern=(int)t.patterns.size();}else if(id==5)t.clips[index].muted=!t.clips[index].muted;else if(id>=100&&id<=105)t.clips[index].color=id-101;changed();}

