    fs::path fileDialog(bool save,const wchar_t*filter,const wchar_t*extension,const fs::path&initial){wchar_t path[32768]{};std::error_code ec;bool directory=fs::is_directory(initial,ec);auto folder=(directory?initial:initial.parent_path()).wstring();auto name=directory?L"":initial.filename().wstring();wcsncpy(path,name.c_str(),32767);OPENFILENAMEW ofn{sizeof ofn};ofn.hwndOwner=window;std::wstring localizedFilter;for(auto part=filter;*part;part+=wcslen(part)+1){localizedFilter+=ui::translate(part);localizedFilter.push_back(0);}localizedFilter.push_back(0);ofn.lpstrFilter=localizedFilter.c_str();ofn.lpstrInitialDir=folder.empty()?nullptr:folder.c_str();ofn.lpstrFile=path;ofn.nMaxFile=32768;ofn.lpstrDefExt=extension;ofn.Flags=OFN_EXPLORER|OFN_NOCHANGEDIR|(save?OFN_OVERWRITEPROMPT:OFN_FILEMUSTEXIST);if((save?GetSaveFileNameW(&ofn):GetOpenFileNameW(&ofn)))return fs::path(path);return {};}
