    bool ensureSaved(){if(warpBusy){notify(L"Wait for Warp processing to finish");return false;}if(sampleBusy){notify(L"Дождись окончания обработки аудио перед сменой проекта");return false;}if(exportBusy){exportControl.cancel=true;notify(L"Отмена рендера… дождись окончания перед закрытием");return false;}finishMidiRecording();finishAudioRecording();if(!modified)return true;int result=MessageBoxW(window,L"Сохранить изменения проекта?",L"VampDAW",MB_YESNOCANCEL|MB_ICONQUESTION);if(result==IDCANCEL)return false;if(result==IDYES)return save();return true;}
    void capturePluginStates(){bool restart=false,playing=engine.playing;try{syncAraTracks(restart);for(int t:channelIds()){if(channel(t).frozen)continue;auto previous=channel(t).pluginStates;channel(t).pluginStates.clear();for(size_t slot=0;slot<plugins[t].size();slot++){Json state=plugins[t][slot]->state();if(state.is_null()&&slot<previous.size())state=previous[slot];channel(t).pluginStates.push_back(state);}}}catch(...){if(restart){engine.start(desiredAudio);engine.playing=playing;}throw;}if(restart){engine.start(desiredAudio);engine.playing=playing;}}
    bool save(){finishMidiRecording();finishAudioRecording();try{fs::path path=projectPath;if(path.empty())path=fileDialog(true,L"VampDAW project (*.vamp)\0*.vamp\0\0",L"vamp",root/L"projects"/(wide(project.name)+L".vamp"));if(path.empty())return false;
            LoadingOperation loading(*this,L"Saving project",path.filename().wstring());bool playing=engine.playing;engine.stop();capturePluginStates();project.name=utf8(path.stem().wstring());saveProject(project,path);projectPath=path;modified=false;publish();engine.start(desiredAudio);engine.playing=playing;notify(L"Проект сохранён: "+path.filename().wstring());return true;
        }catch(const std::exception&e){engine.start(desiredAudio);error(e.what());return false;}}
    void syncPlugins(const Project*previous=nullptr){LoadingOperation loading(*this,L"Restoring plugins");size_t loadedCount=0,totalCount=0;for(int t:channelIds())totalCount+=channel(t).pluginPaths.size();bool wasPlaying=engine.playing.load();engine.stop();for(int i=(int)project.tracks.size();i<TrackCount;i++)plugins[i].clear();for(int t:channelIds()){if(channel(t).frozen){loadedCount+=channel(t).pluginPaths.size();plugins[t].clear();continue;}auto&paths=channel(t).pluginPaths;bool same=paths.size()==plugins[t].size();if(same)for(size_t s=0;s<paths.size();s++)same&=wide(paths[s])==plugins[t][s]->path.wstring()&&((s<channel(t).pluginStates.size()&&channel(t).pluginStates[s].is_object()&&channel(t).pluginStates[s].contains("ara"))==plugins[t][s]->araActive());if(same){const Track*prior=previous?(t==MasterChannel?&previous->master:t<(int)previous->tracks.size()?&previous->tracks[t]:nullptr):nullptr;if(!prior||prior->pluginStates!=channel(t).pluginStates)for(size_t s=0;s<channel(t).pluginStates.size()&&s<plugins[t].size();s++){if(plugins[t][s]->araActive())plugins[t][s]->syncAra(makeAraTrackContext(project,t));plugins[t][s]->restore(channel(t).pluginStates[s]);}loadedCount+=paths.size();loading.update(wide(channel(t).name),totalCount?loadedCount/double(totalCount):1);continue;}plugins[t].clear();
            for(size_t s=0;s<paths.size();s++){loading.update(fs::path(wide(paths[s])).filename().wstring(),totalCount?loadedCount++/double(totalCount):0);auto plug=std::make_shared<Plugin>();std::string message;std::optional<AraTrackContext>araContext;if(s<channel(t).pluginStates.size()&&channel(t).pluginStates[s].is_object()&&channel(t).pluginStates[s].contains("ara"))araContext=makeAraTrackContext(project,t);if(plug->load(wide(paths[s]),engine.rate,message,araContext?&*araContext:nullptr)){if(s<channel(t).pluginStates.size())plug->restore(channel(t).pluginStates[s]);}else{plug->path=wide(paths[s]);plug->info.name="Missing: "+utf8(plug->path.stem().wstring());notify(L"Plugin unavailable: "+wide(message));}plugins[t].push_back(plug);}}
        publish();if(engine.hostWindow){engine.start(desiredAudio);restartInput();}engine.playing=wasPlaying;}
    void open(){if(!ensureSaved())return;auto path=fileDialog(false,L"Projects (*.vamp;*.flp;*.als)\0*.vamp;*.flp;*.als\0\0",L"vamp",root/L"projects");if(path.empty())return;if(lower(path.extension().wstring())!=L".vamp"){importForeignProject(path);return;}try{LoadingOperation loading(*this,L"Loading project",path.filename().wstring());auto loaded=loadProject(path);compile(loaded);++importGeneration;engine.stop();engine.beat=0;patternPreview=false;project=std::move(loaded);playlistRowOffset=projectTreeScroll=0;mixerPeakHold.fill(0);projectTreeFolder=-1;projectPath=path;syncPlugins();modified=false;undoStack.clear();redoStack.clear();select(0);notify(L"Открыт "+path.filename().wstring());notifyProjectAudio();}catch(const std::exception&e){error(e.what());}}
