    void switchAutomation(int target,int slot,uint32_t parameter,const std::string&name){automationPoint=-1;auto&t=channel(selected);auto same=[&](const AutomationLane&line){return line.target==target&&(target!=2||(line.slot==slot&&line.parameter==parameter));};AutomationLane current{t.automationTarget,t.automationSlot,t.automationParam,t.automationName,t.automationEnabled,t.automation};if(same(current))return;auto lanes=t.automationLanes;AutomationLane next{target,slot,parameter,name,false,{}};auto existing=std::find_if(lanes.begin(),lanes.end(),same);if(existing!=lanes.end()){next=*existing;lanes.erase(existing);}if(!current.points.empty())lanes.push_back(current);if(lanes.size()>63){notify(L"Максимум 64 линии автоматизации на канал");return;}history();t.automationLanes=std::move(lanes);t.automationTarget=next.target;t.automationSlot=next.slot;t.automationParam=next.parameter;t.automationName=next.name;t.automationEnabled=next.enabled;t.automation=std::move(next.points);changed();}
    void automationMenu(){HMENU menu=CreatePopupMenu();auto&t=channel(selected);AppendMenuW(menu,MF_STRING,1001,L"Громкость / Volume");AppendMenuW(menu,MF_STRING,1002,L"Панорама / Pan");if(!t.automationLanes.empty()){HMENU saved=CreatePopupMenu();for(size_t i=0;i<t.automationLanes.size();i++)AppendMenuW(saved,MF_STRING,3000+i,wide(t.automationLanes[i].name).c_str());AppendMenuW(menu,MF_POPUP,(UINT_PTR)saved,L"Нарисованные линии");}std::vector<std::pair<int,PluginParameter>>parameters;
        for(size_t slot=0;slot<plugins[selected].size();slot++){auto available=plugins[selected][slot]->parameters();if(available.empty())continue;HMENU sub=CreatePopupMenu();for(auto&param:available){if(parameters.size()>=800)break;AppendMenuW(sub,MF_STRING,2000+parameters.size(),wide(param.name).c_str());parameters.push_back({(int)slot,param});}AppendMenuW(menu,MF_POPUP,(UINT_PTR)sub,(number(slot+1)+L" / "+wide(plugins[selected][slot]->info.name)).c_str());}
        POINT point;GetCursorPos(&point);int id=TrackPopupMenu(menu,TPM_RETURNCMD|TPM_RIGHTBUTTON,point.x,point.y,0,window,nullptr);DestroyMenu(menu);if(id==1001||id==1002)switchAutomation(id==1001?0:1,-1,0,id==1001?"Volume":"Pan");else if(id>=2000&&id-2000<(int)parameters.size()){auto&item=parameters[id-2000];switchAutomation(2,item.first,item.second.id,std::to_string(item.first+1)+" / "+plugins[selected][item.first]->info.name+" / "+item.second.name);}else if(id>=3000&&id-3000<(int)t.automationLanes.size()){auto lane=t.automationLanes[id-3000];switchAutomation(lane.target,lane.slot,lane.parameter,lane.name);}}
    int chooseDestination(int source,bool master=true){HMENU menu=CreatePopupMenu();if(master)AppendMenuW(menu,MF_STRING,MasterChannel+1,L"MASTER");for(int base=0;base<(int)project.tracks.size();base+=16){HMENU group=CreatePopupMenu();for(int i=base;i<std::min(base+16,(int)project.tracks.size());i++)if(i!=source)AppendMenuW(group,MF_STRING,i+1,(number(i+1)+L" / "+wide(channel(i).name)).c_str());AppendMenuW(menu,MF_POPUP,(UINT_PTR)group,(number(base+1)+L"–"+number(std::min(base+16,(int)project.tracks.size()))).c_str());}POINT pt;GetCursorPos(&pt);int id=TrackPopupMenu(menu,TPM_RETURNCMD,pt.x,pt.y,0,window,nullptr);DestroyMenu(menu);return id?id-1:-1;}
